// Same cached instance is reached two ways from the importer. `foo` is projected
// narrowly at site A, but site B escapes the whole module object, so `baz` (and
// every other export) is conservatively reachable too.
function foo(s) {
  const str = String(s);
  const t = [41, 43, 47, 53, 59, 61];
  let h = 7;
  for (let i = 0; i < str.length; i++) {
    h = (h * t[i % t.length] + str.charCodeAt(i)) >>> 0;
  }
  let r = '';
  for (let k = 0; k < 5; k++) {
    r += (h % 36).toString(36);
    h = (h >>> 3) + 1;
  }
  return `iu-target:foo:${r}`;
}
exports.foo = foo;

function baz(s) {
  const str = String(s);
  let acc = 0;
  for (let i = 0; i < str.length; i++) {
    acc = (acc + str.charCodeAt(i) * (i * 2 + 1)) >>> 0;
  }
  acc = (acc ^ (acc >>> 7)) >>> 0;
  return `iu-target:baz:${(acc >>> 0).toString(36)}`;
}
exports.baz = baz;
